require "test_helper"
require_relative "../test_helpers/session_test_helper"

# The passkey flow end to end (generated by maquina:passkeys), with
# WebAuthn::FakeClient as the browser and the authenticator.
class PasskeysTest < ActionDispatch::IntegrationTest
  setup do
    @user = User.create!(account: Account.create!(name: "Acme"), email_address: "passkey@example.com")
  end

  test "adds a passkey and signs in with it" do
    sign_in_as @user
    register_passkey
    assert_response :created
    passkey = @user.passkeys.sole

    sign_out
    sign_in_with_passkey(@user)

    assert_response :success
    assert response.parsed_body["redirect_url"].present?
    assert cookies["session_id"].present?
    assert passkey.reload.last_used_at
  end

  test "a challenge signs in once" do
    sign_in_as @user
    register_passkey
    sign_out

    post session_passkey_challenge_path, as: :json
    assertion = webauthn_client.get(challenge: response.parsed_body["challenge"], rp_id: WebAuthn.configuration.rp_id,
      user_verified: true, user_handle: Base64.urlsafe_decode64(@user.reload.webauthn_id))
    post session_passkey_path, params: {credential: assertion}, as: :json
    assert_response :success

    post session_passkey_path, params: {credential: assertion}, as: :json
    assert_response :unprocessable_entity
  end

  test "a passkey needs user verification" do
    sign_in_as @user
    post passkey_challenge_path, as: :json
    credential = webauthn_client.create(challenge: response.parsed_body["challenge"], rp_id: WebAuthn.configuration.rp_id,
      user_verified: false)

    post passkeys_path, params: {credential: credential}, as: :json

    assert_response :unprocessable_entity
    assert_empty @user.passkeys
  end

  test "a removed passkey no longer signs in" do
    sign_in_as @user
    register_passkey
    @user.passkeys.destroy_all
    sign_out

    sign_in_with_passkey(@user)

    assert_response :not_found
    assert response.parsed_body["credential_id"].present?
  end

  test "a blocked user cannot sign in with a passkey" do
    sign_in_as @user
    register_passkey
    sign_out
    @user.block!

    sign_in_with_passkey(@user)

    assert_response :unprocessable_entity
  end

  test "adding a passkey needs a recent sign-in" do
    sign_in_as @user
    Current.session.update_column(:created_at, 2.hours.ago)

    post passkey_challenge_path, as: :json

    assert_response :unauthorized
    assert_equal new_session_url, response.parsed_body["redirect_url"]
  end

  test "renames and removes a passkey" do
    sign_in_as @user
    register_passkey
    passkey = @user.passkeys.sole

    patch passkey_path(passkey), params: {passkey: {name: "Work laptop"}}
    assert_redirected_to passkeys_path
    assert_equal "Work laptop", passkey.reload.name

    delete passkey_path(passkey)
    assert_redirected_to passkeys_path
    assert_empty @user.passkeys.reload
  end
end
